// Where a phone held upright keeps a pixel cutscene still in frame (js/vn.js, focus), for the few shots whose subject
// sits near an edge. Upright, a still shows in a 4:3 band, three quarters of its width; the band is centred unless a
// shot is listed here, as a percentage across the still (0 keeps the left three quarters, 100 the right). The cut-*.js
// files are generated by the cutscene pipeline, so the list lives here instead.
(function () {
  if (!SD.vn) return;
  const FOCUS = {
    'cut-the-crowning-1': 0,            // Noor and the bishop, far left
    'cut-ask-2': 0,                     // Noor at the left edge
    'cut-a-choice-not-a-gift-1': 100,   // Freya by the fire, far right
    'cut-freya-at-camp-1': 100,         // Freya, far right
    'cut-the-rail-let-1': 85,           // the figure at the right
    'cut-c7-roles-1': 100,              // the two at the right of the room
    'cut-c7-roof-2': 10                 // the words laid over the left of the shot
  };
  Object.entries(FOCUS).forEach(([id, x]) => { const s = SD.vn.art.scenes[id]; if (s) s.focus = x + '% 50%'; });
})();
